package ru.truetv.bridge;
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import javax.net.ssl.*;
/** Real loopback mutual TLS/payload tests; no Android/device claims. */
public final class BridgeCheck {
 static int checks;static void check(boolean n,String label){if(!n)throw new AssertionError(label);checks++;}
 interface Job {void run()throws Exception;}static void reject(Job r)throws Exception {try{r.run();throw new AssertionError("Unexpected success");}catch(IOException|IllegalArgumentException good){checks++;}}
 static final class Memory implements Wire.Store {List<byte[]> saved=new ArrayList<>();int discarded;public Wire.Target create(Wire.Item i){return new Wire.Target(){ByteArrayOutputStream bytes=new ByteArrayOutputStream();public OutputStream stream(){return bytes;}public String publish(){saved.add(bytes.toByteArray());return i.name;}public void discard(){discarded++;}};}}
 static final class Event implements Transfer.Events {final CountDownLatch done=new CountDownLatch(1);boolean success;public void update(int i,String n,long b,long t){}public void finished(boolean s,String d){success=s;done.countDown();}}
 static final Transfer.ClientEvents quiet=new Transfer.ClientEvents(){public void waiting(String tv,String fp,String code){}public void accepted(String fp){}public void update(int i,String n,long b,long t){}};
 static Thread serve(Transfer.Receiver r){Thread t=new Thread(()->{try{r.accept();}catch(IOException expected){}});t.start();return t;}
 public static void main(String[] args){try{run();}catch(Throwable e){e.printStackTrace();System.exit(1);}}
 private static void run()throws Exception {
  File root=Files.createTempDirectory("totv-wire-").toFile();Identity tv=Identity.load(new File(root,"tv")),phone=Identity.load(new File(root,"phone"));check(tv.fingerprint().equals(Identity.load(new File(root,"tv")).fingerprint()),"stable identity survives reload");check(!tv.fingerprint().equals(phone.fingerprint()),"distinct device keys");tv.certificate.verify(tv.certificate.getPublicKey());check(tv.certificate.getNotAfter().getTime()>System.currentTimeMillis(),"valid self-signed leaf");check(Wire.name("../../evil.apk").equals("evil.apk"),"path traversal reduced to basename");check(Wire.name("C:\\path\\rom.nes").equals("rom.nes"),"Windows paths cannot escape Downloads");reject(()->Wire.name(".."));reject(()->new Wire.Item("a","text/plain",-2));check(Wire.local(InetAddress.getByName("127.0.0.1"))&&!Wire.local(InetAddress.getByName("8.8.8.8")),"local network boundary");
  byte[] data=new byte[2*1024*1024+97];new Random(9).nextBytes(data);Memory store=new Memory();Event event=new Event();String[] tvCode={null},clientCode={null};Transfer.Receiver r=new Transfer.Receiver(tv,"TV",store,(offer,fp,code)->{check(fp.equals(phone.fingerprint()),"approval sees authenticated phone key");tvCode[0]=code;return true;},event);Thread accept=serve(r);Transfer.Sender send=new Transfer.Sender();List<String> names=send.send(phone,InetAddress.getLoopbackAddress(),r.port(),tv.fingerprint(),new Wire.Offer("Phone",Arrays.asList(new Wire.Item("game.nes","application/octet-stream",data.length),new Wire.Item("empty.txt","text/plain",0),new Wire.Item("unknown.bin","application/octet-stream",-1))),i->new ByteArrayInputStream(i==1?new byte[0]:data),new Transfer.ClientEvents(){public void waiting(String n,String fp,String code){clientCode[0]=code;}public void accepted(String fp){}public void update(int i,String n,long b,long t){}});check(event.done.await(5,TimeUnit.SECONDS)&&event.success,"server confirms full batch");check(names.size()==3&&store.saved.size()==3,"three files acknowledged");check(Arrays.equals(data,store.saved.get(0))&&store.saved.get(1).length==0&&Arrays.equals(data,store.saved.get(2)),"large/chunked/empty/unknown-size bytes exact");check(tvCode[0].equals(clientCode[0]),"both devices display same authenticated-connection code");r.close();accept.join(3000);
  store=new Memory();event=new Event();r=new Transfer.Receiver(tv,"TV",store,(o,f,c)->false,event);accept=serve(r);final Transfer.Receiver denied=r;reject(()->new Transfer.Sender().send(phone,InetAddress.getLoopbackAddress(),denied.port(),tv.fingerprint(),new Wire.Offer("Phone",Arrays.asList(new Wire.Item("a.txt","text/plain",1))),i->new ByteArrayInputStream(new byte[]{1}),quiet));check(store.saved.isEmpty()&&store.discarded==0,"rejected offer creates no file");r.close();accept.join(3000);
  store=new Memory();event=new Event();r=new Transfer.Receiver(tv,"TV",store,(o,f,c)->true,event);accept=serve(r);final Transfer.Receiver mismatch=r;reject(()->new Transfer.Sender().send(phone,InetAddress.getLoopbackAddress(),mismatch.port(),phone.fingerprint(),new Wire.Offer("Phone",Arrays.asList(new Wire.Item("a","text/plain",1))),i->new ByteArrayInputStream(new byte[]{1}),quiet));check(store.saved.isEmpty(),"wrong TV pin cannot publish files");r.close();accept.join(3000);
  store=new Memory();event=new Event();r=new Transfer.Receiver(tv,"TV",store,(o,f,c)->true,event);accept=serve(r);final Transfer.Receiver shortFile=r;reject(()->new Transfer.Sender().send(phone,InetAddress.getLoopbackAddress(),shortFile.port(),tv.fingerprint(),new Wire.Offer("Phone",Arrays.asList(new Wire.Item("short.txt","text/plain",10))),i->new ByteArrayInputStream(new byte[]{1}),quiet));check(event.done.await(5,TimeUnit.SECONDS)&&!event.success&&store.saved.isEmpty()&&store.discarded==1,"interrupted/mismatched file discarded, never published");r.close();accept.join(3000);
  store=new Memory();event=new Event();final Event cancelled=event;final Transfer.Receiver[] cancelReceiver=new Transfer.Receiver[1];r=new Transfer.Receiver(tv,"TV",store,(o,f,c)->true,new Transfer.Events(){boolean stopped;public void update(int i,String n,long b,long t){if(!stopped){stopped=true;cancelReceiver[0].cancel();}}public void finished(boolean ok,String d){cancelled.finished(ok,d);}});cancelReceiver[0]=r;accept=serve(r);final Transfer.Receiver cancel=r;reject(()->new Transfer.Sender().send(phone,InetAddress.getLoopbackAddress(),cancel.port(),tv.fingerprint(),new Wire.Offer("Phone",Arrays.asList(new Wire.Item("cancel.bin","application/octet-stream",data.length))),i->new ByteArrayInputStream(data),quiet));check(event.done.await(5,TimeUnit.SECONDS)&&!event.success&&store.saved.isEmpty()&&store.discarded==1,"cancelling an active TLS stream discards partial target");r.close();accept.join(3000);
  store=new Memory();event=new Event();r=new Transfer.Receiver(tv,"TV",store,(o,f,c)->true,event);accept=serve(r);try(SSLSocket raw=(SSLSocket)phone.tls(tv.fingerprint()).getSocketFactory().createSocket(InetAddress.getLoopbackAddress(),r.port())){raw.startHandshake();DataOutputStream o=new DataOutputStream(raw.getOutputStream());DataInputStream in=new DataInputStream(raw.getInputStream());o.writeInt(Wire.MAGIC);o.write(Wire.random());o.flush();check(in.readInt()==Wire.MAGIC,"raw authenticated test handshake");Wire.text(in,256);byte[] nonce=new byte[32];in.readFully(nonce);new Wire.Offer("Phone",Arrays.asList(new Wire.Item("corrupt.bin","application/octet-stream",1))).write(o);o.flush();check(in.readInt()==Wire.WAIT&&in.readInt()==Wire.ACCEPT,"raw authenticated offer accepted");o.writeInt(1);o.writeByte(42);o.writeInt(0);o.write(new byte[32]);o.flush();check(event.done.await(5,TimeUnit.SECONDS)&&!event.success&&store.saved.isEmpty()&&store.discarded==1,"wrong SHA256 never publishes an otherwise complete file");}r.close();accept.join(3000);
  Decision decision=new Decision();decision.answer(3);decision.answer(1);check(decision.await(1)==3,"stale decision cannot replace first answer");System.out.println("PASS "+checks+" bridge identity/TLS/stream/reject/cleanup checks");
 }
}
